def get_exercises(muscle_group=None):
    """Get exercises by muscle group"""
    params = {"language": 2, "limit": 50}  # English
    if muscle_group:
        params["muscles"] = muscle_group

    response = requests.get(
        f"{BASE_URL}/exercise",
        params=params,
        headers={"Authorization": f"Token {WGER_API_KEY}"}
    )
    return response.json()

